SELECT fn_cp_import_case('ordre-incident-lors-ceremonie-officielle', '{"slug": "ordre-incident-lors-ceremonie-officielle", "title": "Un homme s''avance vers l''estrade en criant pendant la minute de silence", "theme_slug": "ordre-public", "difficulty": "difficile", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 30, "situation_text": "Il est 11 heures. Lors d''une cérémonie officielle au monument aux morts, un homme s''avance soudainement vers l''estrade en criant durant la minute de silence, cet incident survenant dans un cadre protocolaire strict et devant de nombreuses personnalités et personnes présentes, cette exposition symbolique et publique rendant votre intervention à la fois nécessaire et particulièrement délicate à mener. Cette configuration, où l''intervention nécessaire pour interrompre ce trouble doit néanmoins s''effectuer avec une mesure appropriée compte tenu de ce cadre protocolaire solennel, impose une action rapide mais mesurée qui évite toute brutalité visible qui pourrait choquer davantage l''ensemble des personnes présentes.\n\nCette situation, caractéristique des interventions qui doivent concilier une nécessité d''action immédiate avec une exposition symbolique maximale devant un public particulièrement sensible au respect de ce cadre cérémoniel, nécessite une gestion qui privilégie la discrétion et la mesure sur toute démonstration de force inutile.\n\nCette configuration nécessite d''intervenir avec mesure et sans brutalité visible face à cet incident, cette exigence particulière restant essentielle compte tenu du cadre protocolaire et de l''exposition publique de cette cérémonie officielle.", "questions": [{"position": 1, "max_points": 5, "label": "Comment intervenez-vous face à cet homme sans brutalité visible durant cette cérémonie officielle ?", "hint": "Cette intervention doit rester mesurée et discrète autant que possible, cette exigence restant essentielle compte tenu du cadre protocolaire et de l''exposition publique de cette cérémonie.", "perfect": "J''interviens rapidement pour neutraliser ce trouble, cette action rapide restant nécessaire pour préserver le déroulement de cette cérémonie officielle solennelle.\n\nJe privilégie une approche mesurée dans mon intervention, cette discrétion relative restant appropriée pour éviter toute image de brutalité qui pourrait choquer l''ensemble des personnes présentes.\n\nJe reste attentive à évacuer cet homme de la zone protocolaire le plus rapidement et le plus discrètement possible, cette action permettant de limiter la perturbation de cette cérémonie.\n\nJe communique si possible avec mes collègues pour coordonner cette intervention de manière fluide, cette coordination restant essentielle pour une action rapide et mesurée.", "points": [{"position": 1, "label": "Intervenir rapidement pour neutraliser ce trouble", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : action rapide préservant la cérémonie.", "groups": [{"position": 1, "keywords": ["trouble neutralisé", "action rapide", "cérémonie préservée"]}]}, {"position": 2, "label": "Privilégier une approche mesurée évitant toute image de brutalité", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Discrétion relative appropriée devant le public présent.", "groups": [{"position": 1, "keywords": ["approche mesurée", "brutalité évitée", "public présent"]}]}, {"position": 3, "label": "Évacuer cet homme de la zone protocolaire rapidement et discrètement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Action limitant la perturbation de la cérémonie.", "groups": [{"position": 1, "keywords": ["évacuation discrète", "zone protocolaire", "perturbation limitée"]}]}, {"position": 4, "label": "Communiquer avec les collègues pour coordonner cette intervention", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Coordination pour une action fluide et mesurée.", "groups": [{"position": 1, "keywords": ["coordination réalisée", "intervention fluide", "action mesurée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment gérez-vous les suites de cet incident après l''évacuation de cet homme ?", "hint": "Ces suites nécessitent une gestion appropriée, tant pour comprendre les motivations de cet homme que pour permettre la reprise sereine de cette cérémonie officielle.", "perfect": "Je reste attentive à comprendre les motivations de cet homme, ces éléments pouvant orienter la qualification appropriée de cet incident et la suite à lui donner.\n\nJe permets la reprise la plus rapide possible de cette cérémonie officielle, cette priorité restant appropriée pour limiter l''impact de cet incident sur son déroulement global.\n\nJe rends compte avec précision de cet incident à ma hiérarchie, cette information étant nécessaire compte tenu du caractère officiel et symbolique de cette cérémonie perturbée.\n\nJe reste attentive à la réaction des personnalités et personnes présentes, cette vigilance restant utile pour apprécier l''impact réel de cet incident sur le déroulement de cette cérémonie.", "points": [{"position": 1, "label": "Rester attentive à comprendre les motivations de cet homme", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : éléments orientant la qualification de l''incident.", "groups": [{"position": 1, "keywords": ["motivations comprises", "qualification orientée", "incident analysé"]}]}, {"position": 2, "label": "Permettre la reprise la plus rapide possible de cette cérémonie", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Priorité limitant l''impact sur le déroulement global.", "groups": [{"position": 1, "keywords": ["reprise rapide", "impact limité", "cérémonie poursuivie"]}]}, {"position": 3, "label": "Rendre compte avec précision de cet incident à la hiérarchie", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Information nécessaire compte tenu du caractère officiel.", "groups": [{"position": 1, "keywords": ["compte rendu précis", "caractère officiel", "hiérarchie informée"]}]}, {"position": 4, "label": "Rester attentive à la réaction des personnalités et personnes présentes", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vigilance appréciant l''impact réel de l''incident.", "groups": [{"position": 1, "keywords": ["réaction observée", "impact apprécié", "personnalités présentes"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment traitez-vous cet homme durant et après cette intervention, quelle que soit la nature de son geste ?", "hint": "Ce traitement doit rester respectueux et professionnel, indépendamment du caractère perturbateur de son geste dans ce cadre cérémoniel particulièrement solennel.", "perfect": "Je reste attentive à traiter cet homme avec le respect professionnel dû à toute personne, indépendamment du caractère perturbateur de son geste dans ce cadre solennel.\n\nJe reste factuelle dans mes échanges avec lui, cette rigueur restant appropriée pour ne pas ajouter à la tension déjà créée par cet incident inattendu.\n\nJe reste attentive à son état, notamment s''il présente des signes de détresse psychologique qui pourraient expliquer ce geste inhabituel durant cette cérémonie.\n\nJe reste consciente que la qualification définitive de cet incident reviendra à ma hiérarchie et aux autorités compétentes, cette réserve restant appropriée à ce stade de mon intervention.", "points": [{"position": 1, "label": "Traiter cet homme avec le respect professionnel dû à toute personne", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : respect indépendant du caractère perturbateur.", "groups": [{"position": 1, "keywords": ["respect professionnel", "geste perturbateur", "traitement approprié"]}]}, {"position": 2, "label": "Rester factuelle dans les échanges pour ne pas ajouter à la tension", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Rigueur appropriée face à cet incident inattendu.", "groups": [{"position": 1, "keywords": ["échanges factuels", "tension non ajoutée", "incident inattendu"]}]}, {"position": 3, "label": "Rester attentive à d''éventuels signes de détresse psychologique", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Signes pouvant expliquer ce geste inhabituel.", "groups": [{"position": 1, "keywords": ["détresse psychologique", "geste expliqué", "signes observés"]}]}, {"position": 4, "label": "Rester consciente que la qualification définitive revient à la hiérarchie", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réserve appropriée à ce stade de l''intervention.", "groups": [{"position": 1, "keywords": ["qualification différée", "autorités compétentes", "réserve appropriée"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('ordre-camping-sauvage-rassemblement-festif', '{"slug": "ordre-camping-sauvage-rassemblement-festif", "title": "Trois cents personnes, aucun organisateur ne se déclare", "theme_slug": "ordre-public", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 5 heures. Vous êtes appelée sur un terrain rural où environ trois cents personnes participent à un rassemblement festif non déclaré depuis la veille, aucun organisateur ne se déclarant comme responsable de cet événement malgré vos demandes répétées, cette absence d''interlocuteur identifié compliquant considérablement votre gestion de cette situation face à un effectif qui reste dérisoire par rapport au nombre de participants présents sur ce terrain. Cette configuration, où s''ajoutent des risques sanitaires réels liés à l''absence d''encadrement de cet événement et un propriétaire du terrain visiblement excédé par cette occupation non autorisée, nécessite une gestion prudente qui privilégie le compte rendu et la sécurité sanitaire plutôt qu''une intervention directe disproportionnée par rapport à vos moyens.\n\nCette situation, caractéristique des rassemblements festifs non déclarés qui se déroulent en milieu rural avec un effectif dérisoire face au nombre de participants, impose une approche mesurée qui reconnaisse les limites réelles de votre capacité d''action immédiate sur ce terrain.\n\nCette configuration nécessite de rendre compte de cette situation et de privilégier la sécurité sanitaire face à cet effectif dérisoire, cette double priorité restant appropriée plutôt qu''une tentative d''intervention directe qui dépasserait manifestement vos moyens sur ce terrain.", "questions": [{"position": 1, "max_points": 5, "label": "Comment rendez-vous compte de cette situation face à cet effectif dérisoire par rapport au nombre de participants ?", "hint": "Ce compte rendu doit rester précis sur l''ampleur de cette situation et sur les limites réelles de votre capacité d''action immédiate face à ce nombre important de participants.", "perfect": "Je transmets avec précision l''ampleur de cette situation, notamment le nombre approximatif de participants et l''absence d''organisateur identifié malgré mes demandes répétées.\n\nJe signale clairement le déséquilibre entre mon effectif présent et le nombre de participants, cette information étant essentielle pour apprécier les limites réelles de mon action immédiate.\n\nJe précise les risques sanitaires observés liés à l''absence d''encadrement de cet événement, ces éléments pouvant orienter utilement la décision de ma hiérarchie sur la suite à donner.\n\nJe reste disponible pour toute instruction complémentaire, cette réactivité restant nécessaire pour adapter au mieux la gestion de cette situation complexe sur ce terrain rural.", "points": [{"position": 1, "label": "Transmettre l''ampleur de cette situation et l''absence d''organisateur", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : ampleur précisée malgré les demandes répétées.", "groups": [{"position": 1, "keywords": ["ampleur transmise", "organisateur absent", "demandes répétées"]}]}, {"position": 2, "label": "Signaler le déséquilibre entre l''effectif présent et le nombre de participants", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information essentielle sur les limites de l''action immédiate.", "groups": [{"position": 1, "keywords": ["déséquilibre signalé", "effectif dérisoire", "limites d''action"]}]}, {"position": 3, "label": "Préciser les risques sanitaires observés liés à l''absence d''encadrement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Éléments orientant la décision hiérarchique.", "groups": [{"position": 1, "keywords": ["risques sanitaires", "encadrement absent", "décision orientée"]}]}, {"position": 4, "label": "Rester disponible pour toute instruction complémentaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réactivité pour adapter la gestion de cette situation.", "groups": [{"position": 1, "keywords": ["disponibilité maintenue", "instruction complémentaire", "situation complexe"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment privilégiez-vous la sécurité sanitaire de ce rassemblement face à ces risques réels ?", "hint": "Cette priorité sanitaire doit primer sur une tentative d''intervention directe disproportionnée par rapport à vos moyens réels sur ce terrain rural isolé.", "perfect": "Je reste attentive aux risques sanitaires les plus immédiats de cette situation, notamment l''accès à l''eau potable et les conditions d''hygiène de ce rassemblement prolongé.\n\nJe sollicite si nécessaire l''intervention de services compétents en matière sanitaire, cette coordination restant appropriée face à l''ampleur de ce rassemblement non encadré.\n\nJe reste attentive à repérer d''éventuelles personnes en difficulté médicale au sein de ce rassemblement, cette vigilance restant prioritaire par rapport à la seule question de la régularité de cet événement.\n\nJe reste consciente que cette priorité sanitaire reste plus réaliste et plus utile qu''une tentative de dispersion immédiate qui dépasserait manifestement mes moyens actuels.", "points": [{"position": 1, "label": "Rester attentive aux risques sanitaires les plus immédiats", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : eau potable et conditions d''hygiène.", "groups": [{"position": 1, "keywords": ["risques sanitaires immédiats", "hygiène observée", "eau potable"]}]}, {"position": 2, "label": "Solliciter l''intervention de services compétents en matière sanitaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Coordination face à l''ampleur du rassemblement.", "groups": [{"position": 1, "keywords": ["services sanitaires", "coordination sollicitée", "rassemblement non encadré"]}]}, {"position": 3, "label": "Repérer d''éventuelles personnes en difficulté médicale", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance prioritaire par rapport à la régularité de l''événement.", "groups": [{"position": 1, "keywords": ["difficulté médicale", "personnes repérées", "vigilance prioritaire"]}]}, {"position": 4, "label": "Reconnaître que cette priorité sanitaire reste plus réaliste qu''une dispersion immédiate", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Réalisme face aux moyens actuels disponibles.", "groups": [{"position": 1, "keywords": ["priorité réaliste", "dispersion écartée", "moyens actuels"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment gérez-vous ce propriétaire du terrain visiblement excédé par cette occupation non autorisée ?", "hint": "Ce propriétaire mérite une écoute attentive et des explications claires sur la gestion envisagée de cette situation, sa frustration restant compréhensible face à cette occupation non autorisée.", "perfect": "J''écoute attentivement ce propriétaire et sa frustration légitime face à cette occupation non autorisée de son terrain depuis la veille.\n\nJe lui explique clairement les limites réelles de mon action immédiate face à ce nombre important de participants et l''absence d''effectif suffisant pour une intervention directe.\n\nJe l''informe des démarches qu''il pourrait entreprendre pour faire valoir ses droits, notamment sur le plan civil, face à cette occupation non autorisée de sa propriété.\n\nJe reste attentive à ne pas lui faire de promesse que je ne pourrais pas tenir sur le délai de résolution de cette situation, cette honnêteté restant essentielle pour préserver sa confiance.", "points": [{"position": 1, "label": "Écouter attentivement ce propriétaire et sa frustration légitime", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : frustration compréhensible face à cette occupation.", "groups": [{"position": 1, "keywords": ["écoute attentive", "frustration légitime", "occupation non autorisée"]}]}, {"position": 2, "label": "Expliquer clairement les limites réelles de l''action immédiate", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Absence d''effectif suffisant pour une intervention directe.", "groups": [{"position": 1, "keywords": ["limites expliquées", "effectif insuffisant", "action immédiate"]}]}, {"position": 3, "label": "Informer des démarches possibles pour faire valoir ses droits", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Voie civile face à cette occupation non autorisée.", "groups": [{"position": 1, "keywords": ["démarches informées", "droits évoqués", "voie civile"]}]}, {"position": 4, "label": "Ne pas faire de promesse qui ne pourrait pas être tenue", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Honnêteté préservant la confiance du propriétaire.", "groups": [{"position": 1, "keywords": ["promesse évitée", "honnêteté maintenue", "confiance préservée"]}]}]}]}'::jsonb);